import unittest
from pricing import price_after_discount, DISCOUNT_TOLERANCE

class TestPricing(unittest.TestCase):
    def test_price_after_discount(self):
        self.assertAlmostEqual(price_after_discount(100.0, 0.0), 100.0)
        self.assertAlmostEqual(price_after_discount(100.0, 25.0), 75.0)
        self.assertAlmostEqual(price_after_discount(100.0, 50.0), 50.0)
        self.assertAlmostEqual(price_after_discount(100.0, 51.0), 50.0)

    def test_discount_tolerance(self):
        self.assertAlmostEqual(DISCOUNT_TOLERANCE, 0.01)

if __name__ == '__main__':
    unittest.main()
